import{_ as a,o as t,c as o,a5 as r}from"./chunks/framework.BwlBv862.js";const h=JSON.parse('{"title":"导入模板与管理配置","description":"","frontmatter":{"title":"导入模板与管理配置","docId":"user.automations.templates","translationKey":"user.automations.templates","locale":"zh","audience":"user","featureStatus":"available","contentStatus":"reviewed","sourceLocale":"en","sourceRevision":"e9847c93a8a75fd5a58cd115b49b8e0bcb091ceda1dbdf2c226b52667eb17e23","translationRevision":"82274eaa2e4b3162b5db46f9f2d805a14b92572a8fe8fe64bfe985371a495dda","order":50},"headers":[],"relativePath":"zh/user/automations/templates.md","filePath":"zh/user/automations/templates.md","lastUpdated":1794611623000}'),i={name:"zh/user/automations/templates.md"};function l(s,e,d,n,c,p){return t(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="import-templates-and-manage-profiles" tabindex="-1">导入模板与管理配置 <a class="header-anchor" href="#import-templates-and-manage-profiles" aria-label="Permalink to &quot;导入模板与管理配置 {#import-templates-and-manage-profiles}&quot;">​</a></h1><h2 id="goal-and-prerequisites" tabindex="-1">目标与前置条件 <a class="header-anchor" href="#goal-and-prerequisites" aria-label="Permalink to &quot;目标与前置条件 {#goal-and-prerequisites}&quot;">​</a></h2><p>复用已审查的单条规则或一组规则，同时避免意外激活效果。你需要 <strong>自动化</strong>、可信的 JSON 文件或目录条目，以及其中操作所需的插件。替换既有设置前，请导出当前配置。</p><h2 id="choose-the-right-surface" tabindex="-1">选择正确的入口 <a class="header-anchor" href="#choose-the-right-surface" aria-label="Permalink to &quot;选择正确的入口 {#choose-the-right-surface}&quot;">​</a></h2><p><code>.tiktemplate.json</code> 文档描述一个事件及其操作，<code>.tikprofile.json</code> 文档则将多个模板归组。在自动化中打开模板对话框，可使用内置或自定义模板、Cloud 模板库或手动模板导入。使用配置工具栏创建、选择、导出配置或手动导入配置。<strong>插件 → 探索</strong> 浏览的是插件；模板与配置应在此处管理。</p><h2 id="review-and-import" tabindex="-1">审查与导入 <a class="header-anchor" href="#review-and-import" aria-label="Permalink to &quot;审查与导入 {#review-and-import}&quot;">​</a></h2><ol><li>打开对应的导入对话框，选择文件或粘贴支持的 JSON。继续前先核对暂存的名称与来源。</li><li>模板需检查触发器、操作类型和参数；配置还需检查条目数量及共有参数。</li><li>将示例目标、媒体路径及观众标识符替换为适合自己环境的值。不要将凭据粘贴到打算分享的文件中。</li><li>明确执行应用或导入，并等待结果。不要假定导入定义处于禁用状态，应检查审核中的 enabled 值。随后选择它们，逐一审查操作和事件，再明确启用需要的项目。</li><li>先进行仅写日志的测试，或先检查定义。HTTP、音频、积分或插件测试可能产生实际效果。</li><li>确认切换前，审核目标成员将启用、其余记录将禁用，包括独立记录及原先禁用的目标成员。副作用仍需触发器/条件；这不是 Cloud 同步。</li></ol><p><code>{{ params.giftName }}</code> 等参数会在应用模板时解析。<code>{{ event.user.uniqueId }}</code> 等运行时引用保留到每个事件发生时处理，而<a href="./variables.html">全局变量</a>在执行时提供共用的已保存值。</p><h2 id="expected-result-and-status" tabindex="-1">预期结果与状态 <a class="header-anchor" href="#expected-result-and-status" aria-label="Permalink to &quot;预期结果与状态 {#expected-result-and-status}&quot;">​</a></h2><p>本地模板和配置的导入、导出入口均可使用。浏览 Cloud 需要对应的宿主能力及账户或服务。目录预览不能证明操作的外部服务正常。缺少插件时，导入定义可能在完成安装配置前无法使用。</p><h2 id="recovery" tabindex="-1">恢复方法 <a class="header-anchor" href="#recovery" aria-label="Permalink to &quot;恢复方法 {#recovery}&quot;">​</a></h2><p>JSON 无效时，请依据报告的解析错误及预期文档类型修正；重命名任意 JSON 文件并不能转换其格式。修订冲突时，请先刷新已保存的规则库再应用。保留导出的正常配置；配置导出不包含哪些数据，请参阅<a href="./../preferences/backups.html">备份</a>。</p><h2 id="operational-details" tabindex="-1">运行细节 <a class="header-anchor" href="#operational-details" aria-label="Permalink to &quot;运行细节 {#operational-details}&quot;">​</a></h2><p>手动模板导入先保存目录文档；应用模板才创建关联动作/事件。解析器在缺少 <code>enabled</code> 时默认 true，应用流程保留这些值。手动配置导入也将条目交给所有者审核。Cloud 目录模板导入保存模板；Cloud 配置导入携带来源信息准备配置变更。不能因来源或预览成功就断言全部禁用。检查最终比较及已保存状态。CLI 导入应明确使用 <code>tiktools template import file.tiktemplate.json --disabled</code> 或 <code>tiktools template profile-import file.tikprofile.json --disabled</code>。</p><p>切换配置会改变启用状态：确认后启用目标成员，禁用所有非成员动作/事件，包括独立记录。目标中原先禁用的成员可能重新启用。确认前检查两类清单。实际副作用仍要求匹配触发器、条件及可用运行时；切换本身不发送 Cloud 同步。</p>',15)])])}const m=a(i,[["render",l]]);export{h as __pageData,m as default};
